SELECT
FROM sample_return_info AS sri LEFT JOIN sample_return_detail AS srd ON sri.ID = srd.main_id AND srd.is_deleted = FALSE WHERE ${params.sqlMap.default} and sri.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sri.create_time desc

